-- UNIMIS PHASE 1B — PARENT/GUARDIAN PORTAL FOUNDATION
create table if not exists public.guardians(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,first_name text not null,middle_name text,last_name text not null,phone text,email text,status text not null default 'active' check(status in('active','inactive','suspended')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(institution_id,user_id));
create table if not exists public.guardian_student_links(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id) on delete cascade,guardian_id uuid not null references public.guardians(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,relationship text not null default 'guardian',is_primary boolean not null default false,can_view_results boolean not null default true,can_view_gpa boolean not null default true,can_view_attendance boolean not null default true,can_view_finance boolean not null default true,status text not null default 'active' check(status in('active','inactive','revoked')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(guardian_id,student_id));
insert into public.permissions(code,name,module,description) values('guardian.portal','Guardian Portal Access','guardian','Access linked student information through the guardian portal') on conflict(code) do update set name=excluded.name,module=excluded.module,description=excluded.description;
insert into public.roles(institution_id,name,code,description,is_system_role,is_active) select i.id,'Parent / Guardian','parent','Controlled access to linked wards',false,true from public.institutions i where i.code='UNIMIS-DEMO-UNIV' on conflict(institution_id,code) do update set name=excluded.name,description=excluded.description,is_active=true,updated_at=now();
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.institutions i on i.id=r.institution_id join public.permissions p on p.code='guardian.portal' where i.code='UNIMIS-DEMO-UNIV' and r.code='parent' on conflict do nothing;
create index if not exists idx_guardians_user on public.guardians(user_id);create index if not exists idx_guardian_student_guardian on public.guardian_student_links(guardian_id);create index if not exists idx_guardian_student_student on public.guardian_student_links(student_id);
alter table public.guardians enable row level security;alter table public.guardian_student_links enable row level security;
drop policy if exists "Guardians can view own profile" on public.guardians;create policy "Guardians can view own profile" on public.guardians for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "Guardians can view own ward links" on public.guardian_student_links;create policy "Guardians can view own ward links" on public.guardian_student_links for select to authenticated using(exists(select 1 from public.guardians g where g.id=guardian_id and g.user_id=(select auth.uid())));
drop policy if exists "Guardians can view linked published course results" on public.course_results;create policy "Guardians can view linked published course results" on public.course_results for select to authenticated using(result_status='published' and exists(select 1 from public.guardian_student_links gsl join public.guardians g on g.id=gsl.guardian_id where gsl.student_id=course_results.student_id and gsl.status='active' and gsl.can_view_results=true and g.user_id=(select auth.uid())));
drop policy if exists "Guardians can view linked published GPA" on public.student_period_results;create policy "Guardians can view linked published GPA" on public.student_period_results for select to authenticated using(status='published' and exists(select 1 from public.guardian_student_links gsl join public.guardians g on g.id=gsl.guardian_id where gsl.student_id=student_period_results.student_id and gsl.status='active' and gsl.can_view_gpa=true and g.user_id=(select auth.uid())));
drop policy if exists "Guardians can view linked student attendance" on public.student_attendance;create policy "Guardians can view linked student attendance" on public.student_attendance for select to authenticated using(exists(select 1 from public.guardian_student_links gsl join public.guardians g on g.id=gsl.guardian_id where gsl.student_id=student_attendance.student_id and gsl.status='active' and gsl.can_view_attendance=true and g.user_id=(select auth.uid())));
drop policy if exists "Guardians can view linked invoices" on public.student_invoices;create policy "Guardians can view linked invoices" on public.student_invoices for select to authenticated using(exists(select 1 from public.guardian_student_links gsl join public.guardians g on g.id=gsl.guardian_id where gsl.student_id=student_invoices.student_id and gsl.status='active' and gsl.can_view_finance=true and g.user_id=(select auth.uid())));
do $$ declare t text;begin foreach t in array array['guardians','guardian_student_links'] loop execute format('drop trigger if exists trg_%I_updated_at on public.%I',t,t);execute format('create trigger trg_%I_updated_at before update on public.%I for each row execute function public.set_updated_at()',t,t);end loop;end $$;
select (select count(*) from public.guardians) guardians,(select count(*) from public.guardian_student_links) ward_links,(select count(*) from public.roles where code='parent') parent_roles;
